BEGIN
 IF current_user IS DISTINCT FROM 'postgres' OR ev IS NULL
 OR NOT mission_factory_owner.keys_exact_v2(ev,ARRAY['schema_version','operation','review_findings','authority_ref','review_ref','review_sha256','authority_sha256','baseline_sha256','request_key','permit_expires_at'])
 OR (ev->>'schema_version') IS DISTINCT FROM 'human-land-cfg-root/1'
 OR (ev->>'operation') IS DISTINCT FROM 'activate_manual_human_staff'
 OR (ev->'review_findings') IS DISTINCT FROM '[0,0,0]'::jsonb
 OR (ev->>'authority_ref') IS NULL OR length((ev->>'authority_ref'))<1
 OR (ev->>'review_ref') IS NULL OR length((ev->>'review_ref'))<1
 OR coalesce((ev->>'review_sha256'),'') !~ '^[0-9a-f]{64}$'
 OR coalesce((ev->>'authority_sha256'),'') !~ '^[0-9a-f]{64}$'
 OR coalesce((ev->>'baseline_sha256'),'') !~ '^[0-9a-f]{64}$'
 OR ((ev->>'request_key'))::uuid IS NULL
 OR (ev->>'permit_expires_at') IS NULL
 OR ((ev->>'permit_expires_at'))::timestamptz<=statement_timestamp()
 OR ((ev->>'permit_expires_at'))::timestamptz>statement_timestamp()+interval '15 minutes'
 THEN RAISE EXCEPTION 'HUMAN_CFG_GENUINE_REVIEW_AUTHORITY_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('human-land-cfg-20261013',13102026));
