 OR mission_public_owner.public_authoring_allowed_v1(false) IS DISTINCT FROM false
 THEN RAISE EXCEPTION 'HUMAN_CFG_PUBLIC_GATE_DRIFT'; END IF;
 FOR public_pin IN SELECT value FROM jsonb_array_elements($publicpins$[{"signature":"mission_factory_owner.quest_publication_scope_v3(uuid,boolean)","ddl_md5":"749af8b1814fe5a5e15fcd2a61429dbe"},{"signature":"mission_factory_owner.quest_public_open_v3(uuid)","ddl_md5":"9f7591ca1b250c2872c7eae765ebecd7"},{"signature":"mission_factory_owner.quest_execution_assert_v4(uuid,boolean)","ddl_md5":"c1817c9d483581bea98960281fe9a87e"},{"signature":"mission_public_owner.public_authoring_allowed_v1(boolean)","ddl_md5":"5e2f03193dc89332d13da9e746714a6f"},{"signature":"mission_factory_owner.c384_human_identity_v1(uuid)","ddl_md5":"ca0225fd2a1486e5050d3a6358e3e10c"},{"signature":"mission_factory_owner.c395_revision_assert_v1(uuid)","ddl_md5":"a70ec1466b5dafa67ea07638c423c047"},{"signature":"mission_factory_owner.c407_identity_v1(uuid)","ddl_md5":"1e98938354fcb8e27cf826ab90f22770"},{"signature":"mission_factory_owner.c407_active_v1(uuid,text)","ddl_md5":"81648004bde571b78c0161701574b22c"},{"signature":"mission_factory_owner.c412_read_identity_v1(uuid)","ddl_md5":"1cd93323b761cb3dce2e532c57c834ba"},{"signature":"mission_factory_owner.c395_active_human_assert_v1(uuid)","ddl_md5":"88db535e51a63c320ed871c6869bef78"},{"signature":"mission_factory_owner.c416_arc_assert_v1(uuid,boolean)","ddl_md5":"25128ad39faa60077da6f10b0f277b1a"},{"signature":"mission_factory_owner.c416_draft_assert_v1(uuid,boolean)","ddl_md5":"32ec00ca959f80230de52b27d01aea2f"}]$publicpins$::jsonb) LOOP
  IF to_regprocedure((public_pin->>'signature')) IS NULL
