 THEN RAISE EXCEPTION 'HUMAN_CFG_ROW_BASELINE_DRIFT'; END IF;
 FOR pin IN SELECT value FROM jsonb_array_elements($pins$[{"schema":"mission_factory_owner","name":"c416_kind_live_v1","oid":"279676","ddl_md5":"ca836584b84f114ede05277e91610235","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"c416_root_kind_register_v1","oid":"279678","ddl_md5":"4a00ed24dbb4456cbc4c85faa5206bd8","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"c444_enabled_v1","oid":"279768","ddl_md5":"2b8d0af96cf3601f48bbfe9f862c9823","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"c444_enrollment_open_v1","oid":"279779","ddl_md5":"f9b57f4a031face736be74500e0753aa","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"manual_authoring_assert_v1","oid":"276254","ddl_md5":"a19a159cdf5a1f7776699f042376be41","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"c400_admission_v1","oid":"279255","ddl_md5":"f131d8ab8af29ffdf68e3f19b7237c8d","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"c464_authoring_admit_v1","oid":"280153","ddl_md5":"22d0edd1c77cffd60c7043cebc558c9a","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"c464_runtime_admit_v1","oid":"280168","ddl_md5":"5888883c32c339668b5690ae5006fe97","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"staff_release_sha_v1","oid":"276293","ddl_md5":"6c764152a8333516ea15d6525c4671f0","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"c474_bind_if_g2_v1","oid":"280199","ddl_md5":"a33c378d6c70c559240e5b49a0cc834a","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"c474_terminal_preview_v1","oid":"280201","ddl_md5":"439a245b591628191b5cceab46679ed5","owner":"postgres","config":["search_path=\"\""]},{"schema":"mission_factory_owner","name":"c485_parent_register_v1","oid":"280249","ddl_md5":"c480c01144699ff0e1aaf7c83191d989","owner":"postgres","config":["search_path=\"\""]}]$pins$::jsonb) LOOP
 SELECT p.oid,md5(pg_get_functiondef(p.oid)) ddl_md5,pg_get_userbyid(p.proowner) owner,to_jsonb(p.proconfig) cfg
 INTO STRICT fn FROM pg_proc p WHERE p.oid=((pin->>'oid'))::oid;
 IF fn.ddl_md5 IS DISTINCT FROM (pin->>'ddl_md5') OR fn.owner IS DISTINCT FROM (pin->>'owner')
 OR fn.cfg IS DISTINCT FROM (pin->'config') THEN RAISE EXCEPTION 'HUMAN_CFG_FUNCTION_DRIFT';END IF;
 END LOOP;
 SELECT * INTO STRICT ready FROM mission_factory_owner.editor_release_readiness WHERE singleton FOR SHARE;
 IF ready.revision_sha256 IS DISTINCT FROM '37dac90525b249f53fc0404b50adb4ed92df0123649326c99260bf656119d806'
 OR ready.observed_revision_sha256 IS DISTINCT FROM ready.revision_sha256
 OR ready.state IS DISTINCT FROM 'enabled' OR ready.scope IS DISTINCT FROM 'staff'
 OR ready.staff_guards_verified IS DISTINCT FROM true OR ready.published_assets_verified IS DISTINCT FROM true
 OR nullif(btrim(ready.independent_review_ref),'') IS NULL THEN RAISE EXCEPTION 'HUMAN_CFG_READY_DRIFT';END IF;
 IF EXISTS(SELECT 1 FROM mission_factory_owner.manual_authoring_admissions_v1 WHERE release_sha256=ready.revision_sha256)
 THEN RAISE EXCEPTION 'HUMAN_CFG_CURRENT_ADMISSION_EXISTS';END IF;
 IF EXISTS(SELECT 1 FROM public.master_v2_sessions WHERE location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND closed_at IS NULL)
 OR mission_factory_owner.c416_kind_live_v1() OR mission_factory_owner.c444_enabled_v1()
 THEN RAISE EXCEPTION 'HUMAN_CFG_STAFF_NOT_QUIESCENT';END IF;
