 ('b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b',ready.revision_sha256,'f335b077-34a1-41c3-94aa-58ec674b649b','0b85f354-9cdb-47e1-baf9-3d266bb7e06b',lease_at,lease_at+interval '120 minutes',ARRAY['create','save','preview','publish','npc_combat','npc_narrative','context_media','roster_assign','variant_commit','episode_roster'],ARRAY[]::uuid[],true);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>2 THEN RAISE EXCEPTION 'HUMAN_CFG_ADMISSION_COUNT';END IF;
 PERFORM mission_factory_owner.c416_root_kind_register_v1('mission-factory-catalog/1.4','1d020c267273134a377991204f38543034a5d40e4aa2e7d492c8922e43c03c13',ARRAY['narrative.scene','combat.encounter','d100.native','terminal.result'],ARRAY['f0856d53-83a6-4de0-bc0c-12c87916e665','b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b']::uuid[],((ev->>'request_key'))::uuid,jsonb_build_object('schema_version','c416-human-authoring-root/1','operation','register_human_kind','source_sha256',(expected#>>'{c416,source_sha256}'),'review_sha256',(ev->>'review_sha256'),'review_findings','[0,0,0]'::jsonb,'authority_sha256',(ev->>'authority_sha256'),'baseline_sha256',(ev->>'baseline_sha256')));
 UPDATE mission_factory_owner.c384_control SET enabled=true WHERE singleton;
 UPDATE mission_factory_owner.c395_control SET prepare_enabled=true,start_enabled=true WHERE singleton;
 UPDATE mission_factory_owner.c407_control SET admission_enabled=true,manual_fato_enabled=true,d100_enabled=true,review_sha256=(ev->>'review_sha256') WHERE singleton;
 UPDATE mission_factory_owner.c412_control SET runtime_enabled=true,terminal_enabled=true,authoring_enabled=true,review_sha256=(ev->>'review_sha256') WHERE singleton;
 UPDATE mission_factory_owner.c444_runtime_control SET enabled=true,review_sha256=(ev->>'review_sha256'),bound_at=lease_at,expires_at=lease_at+interval '120 minutes' WHERE singleton;
 rows_now:=jsonb_build_object('c384',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c384_control hrow WHERE singleton),'c395',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c395_control hrow WHERE singleton),'c407',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c407_control hrow WHERE singleton),'c412',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c412_control hrow WHERE singleton),'c416',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c416_kind_admission hrow WHERE singleton),'c444',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c444_runtime_control hrow WHERE singleton),'c463',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c463_optin_control hrow WHERE singleton),'c464',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c464_control hrow WHERE singleton),'manual',(SELECT coalesce(jsonb_agg(to_jsonb(hrow) ORDER BY actor_user,release_sha256),'[]'::jsonb) FROM mission_factory_owner.manual_authoring_admissions_v1 hrow),'provider_admissions',(SELECT coalesce(jsonb_agg(jsonb_build_object('enabled',enabled,'expires_at',expires_at) ORDER BY enabled,expires_at),'[]'::jsonb) FROM mission_factory_owner.provider_authoring_admissions hrow));
 IF jsonb_build_object('public_authoring_gate',(SELECT jsonb_build_object('enabled',enabled,'release_sha256',release_sha256,'provider_enabled',provider_enabled) FROM mission_public_owner.public_authoring_gate_v1 WHERE singleton),'fixed_gates',(SELECT jsonb_build_object('staff_enabled',staff_enabled,'public_enabled',public_enabled,'public_staff_enabled',public_staff_enabled,'scheduler_staff_enabled',scheduler_staff_enabled,'scheduler_public_enabled',scheduler_public_enabled) FROM mission_factory_owner.quest_fixed30_admission WHERE singleton)) IS DISTINCT FROM public_before THEN RAISE EXCEPTION 'HUMAN_CFG_PUBLIC_SCOPE_CHANGED'; END IF;
